using System.Collections.Generic;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "DiceActionLogic_RandomCompanion", menuName = "Data/Battle/Logics/Dice Action/Random Companion Dice")]
public class DiceActionLogic_RandomCompanion : DiceActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActionGrabbed()
	{
		base.ActionGrabbed();
		List<GameObject> activeCompanions = currentCompanions.ActiveCompanions;
		List<GameObject> list = new List<GameObject>();
		if (activeCompanions.Count > 0)
		{
			list.Add(activeCompanions.PickRandom());
		}
		actionGameState.SetTargetOnActions(list);
		actionGameState.SetHighlightTargetOnActions(activeCompanions);
	}
}
